/* Стили дашборда: только семантические токены --g-*, отступы — шкала --g-spacing-*. */

.dashboard {
    /* CSS API DashKit: виджеты в режиме редактирования остаются читаемыми. */
    --dashkit-grid-item-edit-opacity: 1;
    --dashkit-grid-item-border-radius: var(--g-border-radius-l);
    --dashkit-overlay-color: var(--g-color-base-simple-hover);
    --dashkit-overlay-border-color: var(--g-color-line-generic);
    --dashkit-placeholder-color: var(--g-color-base-info-light);
    --dashkit-placeholder-opacity: 1;

    box-sizing: border-box;
    min-height: 100vh;
    padding: var(--g-spacing-6);
    background: var(--g-color-base-background);
}

/* Фиксированная панель добавления виджетов не должна перекрывать нижний ряд. */
.dashboard_editing {
    padding-bottom: calc(var(--g-spacing-10) * 3);
}

.dashboard__toolbar {
    margin-bottom: var(--g-spacing-4);
}

.dashboard__heading {
    flex: 1 1 320px;
    min-width: 0;
}

.dashboard__actions {
    flex-shrink: 0;
}

.dashboard__empty {
    padding: var(--g-spacing-10) var(--g-spacing-6);
    margin-bottom: var(--g-spacing-4);
    text-align: center;
}

/* ---------- Виджет ---------- */

.widget {
    --g-card-border-radius: var(--g-border-radius-l);

    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow: hidden;
    background: var(--g-color-base-float);
}

.widget__header {
    flex-shrink: 0;
    padding: var(--g-spacing-3) var(--g-spacing-4) var(--g-spacing-2);
}

.widget__header-icon {
    flex-shrink: 0;
    color: var(--g-color-text-secondary);
}

.widget__title {
    flex: 1;
    min-width: 0;
}

.widget__body {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    padding: 0 var(--g-spacing-4) var(--g-spacing-3);
}

.widget_kpi .widget__body {
    overflow: hidden;
}

.widget__flexible {
    flex: 1;
    min-width: 0;
}

.widget__fixed {
    flex-shrink: 0;
}

.widget__time {
    flex-shrink: 0;
    width: 48px;
}

.widget__list {
    margin: 0;
    padding: 0;
    list-style: none;
}

.widget__scroll-x {
    max-width: 100%;
    overflow-x: auto;
}

.widget__table {
    min-width: 520px;
}

@media (max-width: 767px) {
    .dashboard {
        padding: var(--g-spacing-4);
    }

    /* В мобильной раскладке DashKit виджеты идут в колонку и получают высоту по содержимому. */
    .widget {
        height: auto;
        min-height: 120px;
    }
}
EOF
npx tsc --noEmit 2>&1 | head -30

